 if (!$errors) { try { update_json('messages',function($messages)use($name,$phone,$message,$service){$messages[]=['id'=>bin2hex(random_bytes(8)),'name'=>$name,'phone'=>$phone,'message'=>$message,'service'=>$service,'date'=>gmdate('c'),'read'=>false];return $messages;}); $_SESSION['last_message']=time(); $_SESSION['sent']=true; header('Location: /?sent=1#contact'); exit; } catch(Throwable $ex){$errors[]='پیام ذخیره نشد؛ لطفاً دوباره تلاش کنید یا تماس بگیرید.';} }
}
